/** Shared language cases: original regression suite and automatic engine parity discovery. */
export const cases=[
 // Semantic fallback now retains Console shorthand for these already supported declarations.
 ['generic declaration with profile Console','Console.WriteLine(1);class A<T>{}','1\n'],
 ['init declaration with profile Console','Console.WriteLine(1);class A{public int X{get;init;}}','1\n'],
 ['long source mode','long x=2147483647L;x++;Console.WriteLine(x);','2147483648\n'],
 ['float source mode','float x=1.25f;Console.WriteLine(x);','1.25\n'],
 ['decimal source mode','decimal x=1.0m;Console.WriteLine(x);','1.0\n'],
 ['hello','Console.WriteLine("Hello, managed world");','Hello, managed world\n'],
 ['precedence','Console.WriteLine(2 + 3 * 4);','14\n'],
 ['Int32 wrap','int x = 2147483647; x++; Console.WriteLine(x);','-2147483648\n'],
 ['Int32 multiplication','int x = 65536; Console.WriteLine(x*x);','0\n'],
 ['integer division','Console.WriteLine(-7 / 2);','-3\n'],
 ['floating division','Console.WriteLine(7.0 / 2);','3.5\n'],
 ['minimum int','Console.WriteLine(-2147483648);','-2147483648\n'],
 ['bitwise','Console.WriteLine((3 << 4) | 2); Console.WriteLine(~0);','50\n-1\n'],
 ['boolean','Console.WriteLine(true && !false);','True\n'],
 ['short circuit','int x=0; bool b=false && ++x>0; bool c=true || ++x>0; Console.WriteLine(x);','0\n'],
 ['if else','int a=3; if(a>2) Console.WriteLine("yes"); else Console.WriteLine("no");','yes\n'],
 ['for','int sum=0; for(int i=0;i<10;i++) sum+=i; Console.WriteLine(sum);','45\n'],
 ['while continue break','int i=0; int total=0; while(true) { i++; if(i==3)continue; if(i==6)break; total+=i; } Console.WriteLine(total);','12\n'],
 ['do while','int x=0; do {x++;} while(x<3); Console.WriteLine(x);','3\n'],
 ['for continue','int s=0; for(int i=0;i<5;i++){if(i==2)continue;s+=i;} Console.WriteLine(s);','8\n'],
 ['ternary','int a=true?2:5; Console.WriteLine(a);','2\n'],
 ['coalescing','string x=null; Console.WriteLine(x??"fallback");','fallback\n'],
 ['array foreach','int[] a=new int[]{1,2,3}; foreach(int v in a)Console.WriteLine(v);','1\n2\n3\n'],
 ['implicit array','var a=new[]{2,4,6}; Console.WriteLine(a[1]);','4\n'],
 ['default array','bool[] a=new bool[3]; Console.WriteLine(a.Length);Console.WriteLine(a[1]);','3\nFalse\n'],
 ['array assignment receiver evaluated once','int[] a=new int[]{10,20};int i=0;a[i++] += 5;Console.WriteLine(i);Console.WriteLine(a[0]);','1\n15\n'],
 ['postfix','int x=2; int y=x++;Console.WriteLine(y);Console.WriteLine(x);','2\n3\n'],
 ['prefix','int x=2; int y=++x;Console.WriteLine(y);Console.WriteLine(x);','3\n3\n'],
 ['method calls','int Add(int a,int b){return a+b;} Console.WriteLine(Add(20,22));','42\n'],
 ['recursion','int F(int n){if(n<2)return n;return F(n-1)+F(n-2);}Console.WriteLine(F(10));','55\n'],
 ['expression body','class P { static int Twice(int n)=>n*2; static void Main(){Console.WriteLine(Twice(21));}}','42\n'],
 ['overloads','class P {static int F(int x)=>1;static int F(double x)=>2;static void Main(){Console.WriteLine(F(1));Console.WriteLine(F(1.5));}}','1\n2\n'],
 ['objects constructor fields','class C{public int Value=2;public C(int v){Value=v;}public int Get(){return Value;}} class P{static void Main(){var c=new C(42);Console.WriteLine(c.Get());}}','42\n'],
 ['object initializer','var c=new C(){X=17};Console.WriteLine(c.X);class C{public int X;}','17\n'],
 ['static initializer dependency','class P{static int A=4;static int B=A+2;static void Main(){Console.WriteLine(B);}}','6\n'],
 ['string value equality','string a="abc";string b="a"+"bc";Console.WriteLine(a==b);','True\n'],
 ['object identity','var a=new N();var b=new N();Console.WriteLine(a==b);Console.WriteLine(a==a);class N{}','False\nTrue\n'],
 ['string library','string s=" Abc ";Console.WriteLine(s.Trim().ToUpper());Console.WriteLine(s.Contains("bc"));','ABC\nTrue\n'],
 ['length','Console.WriteLine("😀".Length);','2\n'],
 ['numeric parse','Console.WriteLine(int.Parse("42"));Console.WriteLine(double.Parse("1.5"));','42\n1.5\n'],
 ['round-to-even conversion','Console.WriteLine(Convert.ToInt32(2.5));Console.WriteLine(Convert.ToInt32(3.5));','2\n4\n'],
 ['array sort','int[] a=new int[]{3,1,2};Array.Sort(a);Array.Reverse(a);foreach(int v in a)Console.WriteLine(v);','3\n2\n1\n'],
 ['caught division','try {int z=0;Console.WriteLine(4/z);}catch(Exception e){Console.WriteLine("caught");}Console.WriteLine("after");','caught\nafter\n'],
 ['filtered catch declaration','try{Console.WriteLine(1);}catch(Exception e) when(true){}','1\n'],
 ['filtered catch selection',
  'try{throw new Exception("saved");}catch(Exception e) when(false){Console.WriteLine("wrong");}' +
  'catch(Exception e) when(true){Console.WriteLine(e.Message);}', 'saved\n'],
 ['throw exception','try{throw new Exception("boom");}catch(Exception e){Console.WriteLine(e.Message);}','boom\n'],
 ['cross-frame catch','int Divide(int x){return 1/x;}try{Console.WriteLine(Divide(0));}catch(Exception e){Console.WriteLine("caught");}','caught\n'],
 ['rethrow','try{try{throw new Exception("again");}catch(Exception e){throw;}}catch(Exception e){Console.WriteLine(e.Message);}','again\n'],
 ['Main args','class P{static void Main(string[] args){Console.WriteLine(args.Length);}}','0\n'],
 ['definite assignment both branches','int x;if(true)x=1;else x=2;Console.WriteLine(x);','1\n'],
];
export const diagnosticCases=[
 ['type mismatch','int x="text";','CS0029'],
 ['unassigned','int x;Console.WriteLine(x);','CS0165'],
 ['short circuit definite assignment','int x;bool b=false && (x=2)>0;Console.WriteLine(x);','CS0165'],
 ['branch definite assignment','bool c=false;int x;if(c)x=1;Console.WriteLine(x);','CS0165'],
 ['unknown name','Console.WriteLine(missing);','CS0103'],
 ['duplicate type','Console.WriteLine(1);class A{}class A{}','CS0101'],
 ['duplicate member','Console.WriteLine(1);class A{int X;int X;}','CS0102'],
 ['multiple Main','class A{static void Main(){}}class B{static void Main(){}}','CS0017'],
 ['missing return','int F(int x){if(x>0)return 1;}Console.WriteLine(F(2));','CS0161'],
 ['break outside loop','break;','CS0139'],
 ['rethrow outside catch','throw;','CS0156'],
 ['unknown type','Missing x=null;','CS0246'],
 ['double to int','int x=1.2;','CS0266'],
 ['const write','const int x=1;x=2;','CS0131'],
 ['no entry','class A {}','CS5001'],
 ['invalid condition','if(1)Console.WriteLine(1);','CS0029'],
 ['filter definite assignment',
  'int value;try{throw new Exception("x");}catch(Exception e) when(value==7){Console.WriteLine(1);}', 'CS0165']
];
export const unsupportedCases=[
 'Console.WriteLine(1);class B{}class A:B{}',
 'class A{static async void Main(){}}',
];
export const languageFixtures=[
 ...cases.map(([name,source,output])=>({id:'compiler/'+name,source,expected:{output}})),
 ...diagnosticCases.map(([name,source,code])=>({id:'compiler/diagnostic/'+name,source,compileFailure:true,diagnosticCodes:[code]})),
 ...unsupportedCases.map(source=>({id:'compiler/unsupported/'+source,source,compileFailure:true}))
];
